namespace Workspace.Domain.Common;

/// <summary>
/// Base type for every persisted entity.
/// </summary>
/// <remarks>
/// Identifiers are UUID v7: globally unique like a v4 GUID, but time-ordered, so
/// B-tree index inserts stay sequential instead of scattering across the index.
/// They are generated by the application rather than the database so that a
/// handler can reference an entity (for example in an audit record or a queued
/// job payload) before the transaction commits.
/// </remarks>
public abstract class Entity
{
    public Guid Id { get; set; } = Guid.CreateVersion7();

    public DateTimeOffset CreatedAt { get; set; }

    public DateTimeOffset UpdatedAt { get; set; }
}

/// <summary>
/// Marks an entity as belonging to exactly one organization (tenant).
/// </summary>
/// <remarks>
/// Every type carrying this interface automatically receives a tenant query
/// filter in <c>WorkspaceDbContext</c>, so a query that forgets its
/// organization predicate still cannot read another tenant's rows.
/// </remarks>
public interface ITenantOwned
{
    Guid OrganizationId { get; }
}
